@section('scripts')<script>const testData={@foreach($tests as $t){{ $t->id }}:{batch:{{ $t->test_batch_id }},title:@json($t->title),duration:{{ $t->duration_minutes }},marks:@json($t->marks_per_question),negative:@json($t->negative_mark),dist:@json($t->difficulty_distribution??['easy'=>0,'medium'=>0,'hard'=>0]),status:@json($t->status),sq:{{ $t->shuffle_questions?'true':'false' }},so:{{ $t->shuffle_options?'true':'false' }}},@endforeach};function editT(id){const t=testData[id];document.getElementById('editTForm').action='/admin/test-engine/tests/'+id;document.getElementById('etBatch').value=t.batch;document.getElementById('etTitle').value=t.title;document.getElementById('etDuration').value=t.duration;document.getElementById('etMarks').value=t.marks;document.getElementById('etNegative').value=t.negative;document.getElementById('etEasy').value=t.dist.easy||0;document.getElementById('etMedium').value=t.dist.medium||0;document.getElementById('etHard').value=t.dist.hard||0;document.getElementById('etStatus').value=t.status;document.getElementById('etShuffleQ').checked=t.sq;document.getElementById('etShuffleO').checked=t.so;openModal('editT');}</script>@endsection
